  "id": 1991260721,
  "name": "SPILLLL ZINE v3 LAUNCH PARTY",
  "venue": "The Common press",
  "address": "118 Bethnal Green Road,  London,  E2 6DG",
  "time": "19:00-21:00",
  "date": "Sep 13",
